/* The glibc arm32 signal personality the hosting shim's activation costume
 * presents to the runtime: the structure layouts (the user context and its
 * machine context, the signal information record, the disposition record,
 * the signal set, the stack record), the disposition flags, the mask
 * operations, the origin codes, the signal numbers and the realtime floor.
 * GENERATED by the glibc personality probe from the glibc 2.39 arm32 headers:
 * sys/ucontext.h (sha256 7336f5c0bdc2c2b23a3e4bdce800c18a001a350a630bd6e429b49a603c6cf0c7)
 * bits/sigaction.h (sha256 b2f76a26bbfa3668859e8e8a93af9321e14083914df0aa0367cdffaabf4ece81)
 * bits/types/siginfo_t.h (sha256 88b1392b88af3a08d908866f4e9c5650c5cddb0c8e021b0a3f8293cef6616feb)
 * bits/siginfo-consts.h (sha256 5eda010ce0233e02cea7c1b8679d42ab61eba23c369702661249eec8fd25785b)
 * bits/signum-generic.h (sha256 0a27898a4f720aeabcafb45eba42b0cd6b9593a6e77bd87019969eda94cf435b)
 * bits/signum-arch.h (sha256 ef1475e1546024be5b12edea07ed215ce3a9b004b1266ba7a3b5e40fb7bbe986)
 * bits/types/stack_t.h (sha256 02b6bb18391305b9311776f1c11b5b9788f3f9ebf804913f7691dd669b568b0b)
 * bits/types/__sigset_t.h (sha256 05291a7d38bb1d0da1ed01c09fe85fa2b1f4d5bc708e06bb930efec672db08d5)
 * bits/sigstack.h (sha256 0bc9d6eb37a657ac4fe8e637a331b2728f1d438c446352d9f8f64f366c757b29)
 * asm/sigcontext.h (sha256 51e5d0278efc695d13e05abf921f4b7f0ca614e4419d8b888f4d0479a461019f)
 * bits/siginfo-arch.h (sha256 4428d18387b270e5e9a8126dbc19b683c82cc79f0b48655b139fa17fc983accf)
 * Every number is read back from a compile of those headers, never typed in
 * by hand: regenerate when the personality's source moves, never edit by
 * hand. These are facts of the C library personality the runtime archives
 * were compiled against, not of the runtime pin: a runtime re-pin leaves
 * them in place. A static assert guards every measured offset and size, so
 * a layout that drifts fails the build, never a run. */
#ifndef RHU_GLIBC_ARM32_H
#define RHU_GLIBC_ARM32_H

#include <stddef.h>
#include <stdint.h>

#ifndef RHU_GLIBC_STATIC_ASSERT
#ifdef __cplusplus
#define RHU_GLIBC_STATIC_ASSERT(cond, msg) static_assert(cond, msg)
#else
#define RHU_GLIBC_STATIC_ASSERT(cond, msg) _Static_assert(cond, msg)
#endif
#endif

/* The signal set: 1024 bits as 32 words; signal n occupies bit n - 1 of
 * word (n - 1) / 32. */
typedef struct rhu_glibc_sigset {
    uint32_t word[32];
} rhu_glibc_sigset;
RHU_GLIBC_STATIC_ASSERT(sizeof(rhu_glibc_sigset) == 128, "rhu_glibc_sigset size");

/* The alternate-stack record inside the user context. */
typedef struct rhu_glibc_stack {
    void *ss_sp;
    int32_t ss_flags;
    uint32_t ss_size;
} rhu_glibc_stack;
RHU_GLIBC_STATIC_ASSERT(sizeof(rhu_glibc_stack) == 12, "rhu_glibc_stack size");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_stack, ss_sp) == 0, "rhu_glibc_stack.ss_sp offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_stack, ss_flags) == 4, "rhu_glibc_stack.ss_flags offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_stack, ss_size) == 8, "rhu_glibc_stack.ss_size offset");

/* The machine context: the interrupted integer registers as a signal
 * handler sees them (r11 is the frame pointer slot, r12 the intra-procedure
 * slot), the program status word, and the fault bookkeeping words. */
typedef struct rhu_glibc_mcontext {
    uint32_t trap_no;
    uint32_t error_code;
    uint32_t oldmask;
    uint32_t arm_r0;
    uint32_t arm_r1;
    uint32_t arm_r2;
    uint32_t arm_r3;
    uint32_t arm_r4;
    uint32_t arm_r5;
    uint32_t arm_r6;
    uint32_t arm_r7;
    uint32_t arm_r8;
    uint32_t arm_r9;
    uint32_t arm_r10;
    uint32_t arm_fp;
    uint32_t arm_ip;
    uint32_t arm_sp;
    uint32_t arm_lr;
    uint32_t arm_pc;
    uint32_t arm_cpsr;
    uint32_t fault_address;
} rhu_glibc_mcontext;
RHU_GLIBC_STATIC_ASSERT(sizeof(rhu_glibc_mcontext) == 84, "rhu_glibc_mcontext size");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_mcontext, trap_no) == 0, "rhu_glibc_mcontext.trap_no offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_mcontext, error_code) == 4, "rhu_glibc_mcontext.error_code offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_mcontext, oldmask) == 8, "rhu_glibc_mcontext.oldmask offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_mcontext, arm_r0) == 12, "rhu_glibc_mcontext.arm_r0 offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_mcontext, arm_r1) == 16, "rhu_glibc_mcontext.arm_r1 offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_mcontext, arm_r2) == 20, "rhu_glibc_mcontext.arm_r2 offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_mcontext, arm_r3) == 24, "rhu_glibc_mcontext.arm_r3 offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_mcontext, arm_r4) == 28, "rhu_glibc_mcontext.arm_r4 offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_mcontext, arm_r5) == 32, "rhu_glibc_mcontext.arm_r5 offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_mcontext, arm_r6) == 36, "rhu_glibc_mcontext.arm_r6 offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_mcontext, arm_r7) == 40, "rhu_glibc_mcontext.arm_r7 offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_mcontext, arm_r8) == 44, "rhu_glibc_mcontext.arm_r8 offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_mcontext, arm_r9) == 48, "rhu_glibc_mcontext.arm_r9 offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_mcontext, arm_r10) == 52, "rhu_glibc_mcontext.arm_r10 offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_mcontext, arm_fp) == 56, "rhu_glibc_mcontext.arm_fp offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_mcontext, arm_ip) == 60, "rhu_glibc_mcontext.arm_ip offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_mcontext, arm_sp) == 64, "rhu_glibc_mcontext.arm_sp offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_mcontext, arm_lr) == 68, "rhu_glibc_mcontext.arm_lr offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_mcontext, arm_pc) == 72, "rhu_glibc_mcontext.arm_pc offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_mcontext, arm_cpsr) == 76, "rhu_glibc_mcontext.arm_cpsr offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_mcontext, fault_address) == 80, "rhu_glibc_mcontext.fault_address offset");

/* The user context handed to a three-argument signal handler. uc_regspace
 * is the coprocessor save list: a sequence of magic-and-size records ended
 * by a zero magic word. */
typedef struct rhu_glibc_ucontext {
    uint32_t uc_flags;
    struct rhu_glibc_ucontext *uc_link;
    rhu_glibc_stack uc_stack;
    rhu_glibc_mcontext uc_mcontext;
    rhu_glibc_sigset uc_sigmask;
    uint32_t uc_regspace[128] __attribute__((aligned(8)));
} rhu_glibc_ucontext;
RHU_GLIBC_STATIC_ASSERT(sizeof(rhu_glibc_ucontext) == 744, "rhu_glibc_ucontext size");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_ucontext, uc_flags) == 0, "rhu_glibc_ucontext.uc_flags offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_ucontext, uc_link) == 4, "rhu_glibc_ucontext.uc_link offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_ucontext, uc_stack) == 8, "rhu_glibc_ucontext.uc_stack offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_ucontext, uc_mcontext) == 20, "rhu_glibc_ucontext.uc_mcontext offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_ucontext, uc_sigmask) == 104, "rhu_glibc_ucontext.uc_sigmask offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_ucontext, uc_regspace) == 232, "rhu_glibc_ucontext.uc_regspace offset");
RHU_GLIBC_STATIC_ASSERT(sizeof(((rhu_glibc_ucontext *)0)->uc_regspace) == 512, "rhu_glibc_ucontext.uc_regspace size");

/* The signal information record: the origin fields a thread-directed
 * signal carries (the sender's process and user ids) at their offsets; the
 * remaining words pad the record to its size. */
typedef struct rhu_glibc_siginfo {
    int32_t si_signo;
    int32_t si_errno;
    int32_t si_code;
    int32_t si_pid;
    uint32_t si_uid;
    int32_t si_pad[27];
} rhu_glibc_siginfo;
RHU_GLIBC_STATIC_ASSERT(sizeof(rhu_glibc_siginfo) == 128, "rhu_glibc_siginfo size");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_siginfo, si_signo) == 0, "rhu_glibc_siginfo.si_signo offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_siginfo, si_errno) == 4, "rhu_glibc_siginfo.si_errno offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_siginfo, si_code) == 8, "rhu_glibc_siginfo.si_code offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_siginfo, si_pid) == 12, "rhu_glibc_siginfo.si_pid offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_siginfo, si_uid) == 16, "rhu_glibc_siginfo.si_uid offset");

/* The disposition record: the handler slot (a plain handler, or under
 * SA_SIGINFO the three-argument form), the mask, the flags, the restorer. */
typedef struct rhu_glibc_sigaction {
    void *sa_handler;
    rhu_glibc_sigset sa_mask;
    int32_t sa_flags;
    void *sa_restorer;
} rhu_glibc_sigaction;
RHU_GLIBC_STATIC_ASSERT(sizeof(rhu_glibc_sigaction) == 140, "rhu_glibc_sigaction size");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_sigaction, sa_handler) == 0, "rhu_glibc_sigaction.sa_handler offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_sigaction, sa_mask) == 4, "rhu_glibc_sigaction.sa_mask offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_sigaction, sa_flags) == 132, "rhu_glibc_sigaction.sa_flags offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_sigaction, sa_restorer) == 136, "rhu_glibc_sigaction.sa_restorer offset");
RHU_GLIBC_STATIC_ASSERT(offsetof(rhu_glibc_sigaction, sa_handler) == 0, "the three-argument handler shares the handler slot");
RHU_GLIBC_STATIC_ASSERT(sizeof(void *) == 4, "the handler slot is one pointer");
RHU_GLIBC_STATIC_ASSERT(sizeof(uint32_t) == 4, "a thread handle is one word");

/* The disposition flags. */
#define RHU_GLIBC_SA_NOCLDSTOP 1
#define RHU_GLIBC_SA_NOCLDWAIT 2
#define RHU_GLIBC_SA_SIGINFO 4
#define RHU_GLIBC_SA_ONSTACK 0x08000000
#define RHU_GLIBC_SA_RESTART 0x10000000
#define RHU_GLIBC_SA_NODEFER 0x40000000
#define RHU_GLIBC_SA_RESETHAND 0x80000000

/* The mask operations. */
#define RHU_GLIBC_SIG_BLOCK 0
#define RHU_GLIBC_SIG_UNBLOCK 1
#define RHU_GLIBC_SIG_SETMASK 2

/* The default, ignore and error dispositions as handler values. */
#define RHU_GLIBC_SIG_DFL ((void *)0)
#define RHU_GLIBC_SIG_IGN ((void *)1)
#define RHU_GLIBC_SIG_ERR ((void *)(intptr_t)-1)

/* The origin codes a signal information record carries. */
#define RHU_GLIBC_SI_USER 0
#define RHU_GLIBC_SI_QUEUE (-1)
#define RHU_GLIBC_SI_TKILL (-6)

/* The signal numbers. */
#define RHU_GSIG_SIGHUP 1
#define RHU_GSIG_SIGINT 2
#define RHU_GSIG_SIGQUIT 3
#define RHU_GSIG_SIGILL 4
#define RHU_GSIG_SIGTRAP 5
#define RHU_GSIG_SIGABRT 6
#define RHU_GSIG_SIGBUS 7
#define RHU_GSIG_SIGFPE 8
#define RHU_GSIG_SIGKILL 9
#define RHU_GSIG_SIGUSR1 10
#define RHU_GSIG_SIGSEGV 11
#define RHU_GSIG_SIGUSR2 12
#define RHU_GSIG_SIGPIPE 13
#define RHU_GSIG_SIGALRM 14
#define RHU_GSIG_SIGTERM 15
#define RHU_GSIG_SIGSTKFLT 16
#define RHU_GSIG_SIGCHLD 17
#define RHU_GSIG_SIGCONT 18
#define RHU_GSIG_SIGSTOP 19
#define RHU_GSIG_SIGTSTP 20
#define RHU_GSIG_SIGTTIN 21
#define RHU_GSIG_SIGTTOU 22
#define RHU_GSIG_SIGURG 23
#define RHU_GSIG_SIGXCPU 24
#define RHU_GSIG_SIGXFSZ 25
#define RHU_GSIG_SIGVTALRM 26
#define RHU_GSIG_SIGPROF 27
#define RHU_GSIG_SIGWINCH 28
#define RHU_GSIG_SIGIO 29
#define RHU_GSIG_SIGPWR 30
#define RHU_GSIG_SIGSYS 31

/* The realtime range: the raw bounds the kernel interface defines, the
 * count of signal numbers, and the first realtime signal the C library
 * hands to applications -- it reserves the two below it for its own thread
 * machinery, so the value an application reads at run time is the floor
 * here, not the raw bound. */
#define RHU_GLIBC_SIGRTMIN_RAW 32
#define RHU_GLIBC_SIGRTMAX 64
#define RHU_GLIBC_NSIG 65
#define RHU_GLIBC_SIGRTMIN_CURRENT 34
RHU_GLIBC_STATIC_ASSERT(RHU_GLIBC_SIGRTMAX == 64, "the realtime ceiling the library reports");

#endif /* RHU_GLIBC_ARM32_H */
